    _argc_util_comp_command
}

_choice_features() {
    _helper_cargo_metadata | jq -b -r '.packages[].features | keys[]' 2>/dev/null
}

_choice_package() {
    _helper_cargo_metadata | jq -b -r '.packages[].name' 2>/dev/null
}

_choice_profile() {
    printf '%s\n' dev release test bench
    local root
    root="$(_helper_cargo_metadata | jq -b -r '.workspace_root // empty' 2>/dev/null)"
    [[ -n "$root" && -f "$root/Cargo.toml" ]] || return 0
    gawk '/^\[profile\./ { line=$0; sub(/^\[profile\./, "", line); sub(/\]$/, "", line); print line }' "$root/Cargo.toml"
}

_choice_target() {
    _argc_util_cache 3600 _helper_target_uncached rustc-target-list
}

_choice_target_bin() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "bin") | .name' 2>/dev/null
}

_choice_target_example() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "example") | .name' 2>/dev/null
}

_choice_target_test() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "test") | .name' 2>/dev/null
}

_helper_cargo_metadata() {
    _argc_util_cache 60 _helper_cargo_metadata_uncached "cargo-metadata:$PWD"
}

_helper_cargo_metadata_uncached() {
    command cargo metadata --no-deps --format-version 1 2>/dev/null
}

_helper_target_uncached() {
    command rustc --print target-list 2>/dev/null
